import 'package:flutter/material.dart';
import 'dashboard_service.dart';

class AdminDashboard extends StatefulWidget { final String role; const AdminDashboard({super.key,required this.role}); @override State<AdminDashboard> createState()=>_AdminDashboardState(); }
class _AdminDashboardState extends State<AdminDashboard>{final service=DashboardService();bool loading=true;String? error;Map<String,dynamic> data={};@override void initState(){super.initState();_load();}Future<void> _load()async{try{final d=await service.adminOverview();if(mounted)setState((){data=d;loading=false;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Text(error!));final stats=data['stats'] is Map?Map<String,dynamic>.from(data['stats']):data;return RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('${widget.role.replaceAll('_',' ')} Dashboard',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),_grid(c,stats),const SizedBox(height:18),Card(child:ListTile(leading:const Icon(Icons.insights),title:const Text('School Analytics'),subtitle:const Text('Live attendance, fees, academics and operations overview'),trailing:const Icon(Icons.chevron_right))) ]));}Widget _grid(BuildContext c,Map<String,dynamic>s){final items=[['Students',s['studentCount']??s['students']??0,Icons.groups],['Teachers',s['teacherCount']??s['teachers']??0,Icons.person],['Attendance',s['attendancePercent']??s['attendance']??0,Icons.fact_check],['Outstanding',s['outstanding']??0,Icons.account_balance_wallet]];return GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:items.length,gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:190,crossAxisSpacing:10,mainAxisSpacing:10,childAspectRatio:1.5),itemBuilder:(c,i)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:Duration(milliseconds:300+i*100),builder:(ctx,v,child)=>Transform.scale(scale:.94+.06*v,child:Opacity(opacity:v,child:child)),child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Icon(items[i][2] as IconData),const SizedBox(height:6),Text('${items[i][1]}',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(items[i][0] as String)]))));}
}
